    void permission(String role,String resource){jdbc.update("INSERT INTO user_role_permission VALUES(?,?)",role,resource);}
    void revoke(String role,String resource){jdbc.update("DELETE FROM user_role_permission WHERE role_id=? AND permission_id=?",role,resource);}
    @AfterEach void cleanup(){io.metersphere.agent.security.AgentTokenContext.clear();if(f!=null)f.cleanup();}
    static void parentField(Object target,Class<?> owner,String name,Object value) throws Exception {var field=owner.getDeclaredField(name);field.setAccessible(true);field.set(target,value);}
    <T>T mapper(Class<T> type,String... resources) throws Exception {
        var env=new org.apache.ibatis.mapping.Environment("isolated",new org.mybatis.spring.transaction.SpringManagedTransactionFactory(),jdbc.getDataSource());var config=new org.apache.ibatis.session.Configuration(env);config.setMapUnderscoreToCamelCase(true);
        for(String name:resources){var resource=new org.springframework.core.io.ClassPathResource(name);try(var stream=resource.getInputStream()){new org.apache.ibatis.builder.xml.XMLMapperBuilder(stream,config,name,config.getSqlFragments()).parse();}}
        return new org.mybatis.spring.SqlSessionTemplate(new org.apache.ibatis.session.SqlSessionFactoryBuilder().build(config)).getMapper(type);
    }
