    @Test void legalSingleAndSelectAllPreserveTheOtherCollectionThenSynchronizeTheRealSource(){
        sourceData();remove(selection(List.of("a1")));app.drain();assertEquals(1L,jdbc.queryForObject("SELECT version FROM plan_review_source_clock WHERE plan_id='plan-A'",Long.class));assertEquals("PASS",jdbc.queryForObject("SELECT status FROM case_review_functional_case WHERE review_id='review-A'",String.class));
        var all=selection(List.of());all.setSelectAll(true);all.setCollectionId("col-A2");remove(all);app.drain();assertEquals(2L,jdbc.queryForObject("SELECT version FROM plan_review_source_clock WHERE plan_id='plan-A'",Long.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM case_review_functional_case",Integer.class));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM plan_review_member_history",Integer.class));
        assertEquals(List.of("b","c"),jdbc.queryForList("SELECT test_plan_case_id FROM bug_relation_case ORDER BY test_plan_case_id",String.class));assertEquals(false,jdbc.queryForObject("SELECT deleted FROM test_plan_case_execute_history WHERE test_plan_case_id='b'",Boolean.class));assertEquals(true,jdbc.queryForObject("SELECT deleted FROM test_plan_case_execute_history WHERE test_plan_case_id='a2'",Boolean.class));
    }
    static void await(java.util.concurrent.CountDownLatch latch){try{if(!latch.await(15,java.util.concurrent.TimeUnit.SECONDS))throw new IllegalStateException("Test coordination timeout");}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new IllegalStateException(interrupted);}}
    @ParameterizedTest @ValueSource(strings={"revocation","unlink"}) void committedSourceDeletionIsOrderedBeforeConcurrentRevocationOrUnlink(String action) throws Exception {
        sourceData();var written=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);var started=new java.util.concurrent.CountDownLatch(1);
        try(var workers=java.util.concurrent.Executors.newFixedThreadPool(2)){
            var source=workers.submit(()->f.tx.executeWithoutResult(s->{remove(selection(List.of("a1")));written.countDown();await(release);}));await(written);
            var other=workers.submit(()->{started.countDown();if(action.equals("revocation"))revoke("source","PROJECT_TEST_PLAN:READ+ASSOCIATION");else f.tx.executeWithoutResult(s->app.unlink("relation-A","g-A","unlink-after-write","owner"));});await(started);
            try{assertThrows(java.util.concurrent.TimeoutException.class,()->other.get(100,java.util.concurrent.TimeUnit.MILLISECONDS));}finally{release.countDown();}
            source.get(20,java.util.concurrent.TimeUnit.SECONDS);other.get(20,java.util.concurrent.TimeUnit.SECONDS);
        }finally{release.countDown();}
        assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM test_plan_functional_case WHERE id='a1'",Integer.class));
        if(action.equals("revocation")){String before=facts();assertThrows(PlanReviewFailure.class,()->remove(selection(List.of("a2"))));assertEquals(before,facts());}
        else{remove(selection(List.of("a2")));app.drain();assertEquals("ENDED",jdbc.queryForObject("SELECT state FROM plan_review_relation",String.class));assertEquals("PASS",jdbc.queryForObject("SELECT status FROM case_review_functional_case",String.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM plan_review_member_history",Integer.class));}
    }
