    @Test void reservedRecoveryRechecksTheOriginalDirectoryWithoutChangingIds(){destinations();var request=createRequest("recover");request.setModuleId("module-A");String payload=JSON.toJSONString(request);var reservation=journal.prepare("project","creator","PLAN_SERVICE","CREATE_PAIR",request.getRequestKey(),payload,request.getReviewSettings(),0);
        jdbc.update("DELETE FROM test_plan_module WHERE id='module-A'");String before=facts();var op=jdbc.queryForMap("SELECT * FROM plan_review_operation WHERE id=?",reservation.id());assertThrows(PlanReviewFailure.class,()->f.tx.executeWithoutResult(s->createTarget.resumeReservedCreation(op,"creator")));assertEquals(before,facts());assertEquals(reservation.planId(),jdbc.queryForObject("SELECT plan_id FROM plan_review_operation WHERE id=?",String.class,reservation.id()));
        jdbc.update("INSERT INTO test_plan_module VALUES('module-A','project','NONE')");try(var numbers=mockStatic(io.metersphere.system.uid.NumGenerator.class)){f.tx.executeWithoutResult(s->createTarget.resumeReservedCreation(op,"creator"));}assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM test_plan WHERE id=?",Integer.class,reservation.planId()));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM case_review WHERE id=?",Integer.class,reservation.reviewId()));
    }
    @ParameterizedTest @ValueSource(strings={"foreign","archived","module"}) void reservedRecoveryRejectsCurrentGroupOwnershipOrStatusDrift(String kind){destinations();var request=createRequest("recover-group");request.setGroupId("group-A");var reservation=journal.prepare("project","creator","PLAN_SERVICE","CREATE_PAIR",request.getRequestKey(),JSON.toJSONString(request),request.getReviewSettings(),0);
        switch(kind){case "foreign"->jdbc.update("UPDATE test_plan SET project_id='foreign' WHERE id='group-A'");case "archived"->jdbc.update("UPDATE test_plan SET status='ARCHIVED' WHERE id='group-A'");case "module"->jdbc.update("UPDATE test_plan SET module_id='module-B' WHERE id='group-A'");}
        String before=facts();var op=jdbc.queryForMap("SELECT * FROM plan_review_operation WHERE id=?",reservation.id());assertThrows(PlanReviewFailure.class,()->f.tx.executeWithoutResult(s->createTarget.resumeReservedCreation(op,"creator")));assertEquals(before,facts());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM test_plan WHERE id=?",Integer.class,reservation.planId()));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM case_review",Integer.class));
    }
    @Test void directoryDeletionUsesTheSameTransactionFenceAsReservedCreation() throws Exception {
        destinations();var request=createRequest("directory-race");request.setModuleId("module-A");var reservation=journal.prepare("project","creator","PLAN_SERVICE","CREATE_PAIR",request.getRequestKey(),JSON.toJSONString(request),request.getReviewSettings(),0);
        var written=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);var started=new java.util.concurrent.CountDownLatch(1);
        try(var workers=java.util.concurrent.Executors.newFixedThreadPool(2)){
            var writer=workers.submit(()->f.tx.executeWithoutResult(s->{try(var numbers=mockStatic(io.metersphere.system.uid.NumGenerator.class)){creation.addFromReservation(request,"creator","/reserved","POST");}written.countDown();await(release);}));await(written);
            var deleter=workers.submit(()->{started.countDown();f.tx.executeWithoutResult(s->{store.lockModules("test_plan_module","project",List.of("module-A"));jdbc.update("DELETE FROM test_plan_module WHERE id='module-A'");});});await(started);
            try{assertThrows(java.util.concurrent.TimeoutException.class,()->deleter.get(100,java.util.concurrent.TimeUnit.MILLISECONDS));}finally{release.countDown();}
            writer.get(20,java.util.concurrent.TimeUnit.SECONDS);deleter.get(20,java.util.concurrent.TimeUnit.SECONDS);
        }finally{release.countDown();}
        assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM test_plan WHERE id=?",Integer.class,reservation.planId()));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM case_review WHERE id=?",Integer.class,reservation.reviewId()));
        try(var numbers=mockStatic(io.metersphere.system.uid.NumGenerator.class)){assertEquals(reservation.planId(),f.tx.execute(s->creation.addFromReservation(request,"creator","/reserved","POST")).getId());}assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM test_plan WHERE id=?",Integer.class,reservation.planId()));
    }
